
/* ---------- config ---------- */
const OWNER_ID = 8693389597;           // @Bazzingarr
const SP_BASE = 'https://newlivezero.kidusspro777.workers.dev';   // your Worker URL (sportapi-worker.js). It keeps the sk_live key secret. Example: 'https://sportapi.YOURNAME.workers.dev'
const SP_KEY = '';    // testing only: calling SportAPI straight from the app shows this key to every fan
const OWNER_WEIGHT = 5;                // owner pick counts as 5 votes

/* ---------- telegram + state ---------- */
const tg = window.Telegram && Telegram.WebApp;
if (tg) { tg.ready(); tg.expand(); try{tg.setHeaderColor('#000000');tg.setBackgroundColor('#000000')}catch(e){} }
const user = tg && tg.initDataUnsafe && tg.initDataUnsafe.user;
const inTG = !!(tg && tg.initData);
const isOwner = (user && user.id === OWNER_ID) || (!inTG && location.hash === '#owner-preview');
const $ = s => document.querySelector(s);
const hap = t => { try{ tg.HapticFeedback.impactOccurred(t||'light') }catch(e){} };

let S;
try { S = JSON.parse(localStorage.getItem('zl4k')) } catch(e){}
S = Object.assign({votes:{}, mine:{}, official:{}, favs:[], custom:[], hidden:[], saved:[], banner:'', team:'', feat:'', locked:[], score:{}, ow:5, bst:'gold', bexp:0, gd:'', gn:0, pick:{}}, S||{});
const save = () => { try{ localStorage.setItem('zl4k', JSON.stringify(S)) }catch(e){} };

if (user) $('#hello').textContent = 'Hi ' + (user.first_name || 'fan') + ', make your call';
if (isOwner) { $('#crown').hidden = false; $('#owner').hidden = false; $('#notowner').hidden = true; }
function showBanner(){ const b=$('#banner'); if (S.bexp && Date.now() > S.bexp) { S.banner=''; S.bexp=0; save(); } b.hidden=!S.banner; b.textContent=S.banner; b.style.background={green:'linear-gradient(90deg,#4be3a1,#a6ffd8)',red:'linear-gradient(90deg,#ff7a8a,#ffb0b9)'}[S.bst]||''; }
showBanner();

/* ---------- navigation ---------- */
document.querySelectorAll('nav button').forEach(b => b.onclick = () => {
  document.querySelectorAll('nav button,.tab').forEach(x => x.classList.remove('on'));
  b.classList.add('on'); $('#t-' + b.dataset.t).classList.add('on'); hap();
  if (b.dataset.t === 'me') renderMe();
  if (b.dataset.t === 'tables') loadTable(lg);
  if (b.dataset.t === 'ranks') loadRanks(rkm);
  if (b.dataset.t === 'live') initIptv();
  if (b.dataset.t === 'hl') loadHl(hlk);
});

/* ---------- matches ---------- */
let day = 0, matches = [], mf = 'all';
const dstr = o => new Date(Date.now() + o*864e5).toLocaleDateString('en-CA');
const TZ = (Intl.DateTimeFormat().resolvedOptions().timeZone) || 'UTC';
['Yesterday','Today','Tomorrow'].forEach((n,i) => {
  const b = document.createElement('button'); b.textContent = n; if (i===1) b.classList.add('on');
  b.onclick = () => { day = i-1; document.querySelectorAll('#days button').forEach(x=>x.classList.remove('on')); b.classList.add('on'); load(); };
  $('#days').appendChild(b);
});
async function load(quiet){
  if (!quiet) $('#list').innerHTML = '<div class="empty">Loading matches…</div>';
  let ev = [], err = '', src = 'SportAPI';
  try { ev = await spFixtures(); } catch(e){ spWhy = e.message; err = e.message; ev = []; }
  if (!Array.isArray(ev)) ev = [];
  matches = ev.filter(f => f && f.home && f.away).map(f => ({ id: dstr(day) + '-' + nz(f.home) + '-' + nz(f.away), home: String(f.home), away: String(f.away), league: String(f.league || 'Football'), time: f.time || '--:--', hs: f.hs == null ? null : f.hs, as: f.as == null ? null : f.as, st: f.st || '', fid: f.fid || null, min: f.min || null, season: f.season || null, hid: f.hid || null, aid: f.aid || null, lid: f.lid || null, kick: f.kick || null }));
  if (err && !matches.length && !S.custom.length) { $('#upd').innerHTML = ''; $('#list').innerHTML = '<div class="empty">Could not load matches.<br><b>' + esc(err) + '</b><br><br><button class="ghost" id="rf">Try again</button></div>'; $('#rf').onclick = () => load(); return; }
  if (day === 0) matches = S.custom.map(c=>({...c})).concat(matches);
  matches = matches.filter(m => m.home && m.away && !S.hidden.includes(m.id));
  render(); try { window.goalWatch && goalWatch(matches); } catch(e){}
  $('#upd').innerHTML = '<span>Updated ' + new Date().toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'}) + ' · live via SportAPI' + '</span><button class="ghost" id="rf">Refresh</button>';
  $('#rf').onclick = () => { try { Object.keys(localStorage).filter(k => k.indexOf('zl_sp_fx_') === 0).forEach(k => localStorage.removeItem(k)) } catch(e){} load(); };
}
setInterval(() => { if (!document.hidden && day === 0 && $('#t-matches').classList.contains('on') && matches.some(m => /live|half/i.test(m.st || ''))) load(true); }, 12e4);
function dist(id){
  const v = S.votes[id] || [0,0,0], o = S.official[id];
  const c = v.slice(); if (o) c[{1:0,X:1,2:2}[o]] += (S.ow || OWNER_WEIGHT);
  const t = c[0]+c[1]+c[2];
  return { t, n: v[0]+v[1]+v[2], p: t ? c.map(x => Math.round(x*100/t)) : null, o };
}
function bar(id){
  const d = dist(id);
  if (!d.p) return '<div class="sub"><span>No predictions yet. Be the first.</span></div>';
  return '<div class="bar"><i class="b1" style="width:'+d.p[0]+'%"></i><i class="bx" style="width:'+d.p[1]+'%"></i><i class="b2" style="width:'+d.p[2]+'%"></i></div>' +
    '<div class="sub"><span>'+d.p[0]+'% · '+d.p[1]+'% · '+d.p[2]+'%</span><span>'+d.n+' votes'+(d.o?' · 👑 pick '+d.o:'')+'</span></div>';
}
function render(){
  const q = $('#q').value.toLowerCase(), by = {};
  const fm = matches.find(m => m.id === S.feat); if (fm) by['📌 Featured'] = [fm];
  matches.filter(m => m.id !== S.feat && (mf === 'all' || (LG_RE[mf] && LG_RE[mf].test(m.league))) && (m.home+m.away+m.league).toLowerCase().includes(q)).forEach(m => (by[m.league] = by[m.league] || []).push(m));
  const ks = Object.keys(by);
  if (!ks.length) { $('#list').innerHTML = '<div class="empty">No matches found for this day.' + (isOwner?' Add one from Me.':'') + '</div>'; renderTeams(); return; }
  $('#list').innerHTML = ks.map(k => '<div class="lg">'+esc(k)+'</div>' + by[k].map(m =>
    '<div class="m'+(m.id===S.feat?' ft':'')+'" data-id="'+m.id+'"><div class="row"><div class="tm">'+tl(m.home)+'<span>'+esc(m.home)+'</span></div><div class="sc">'+
    (m.hs!=null&&m.hs!==''?m.hs+' - '+m.as:m.time)+badge(m)+'</div><div class="tm r">'+tl(m.away)+'<span>'+esc(m.away)+'</span></div></div>'+bar(m.id)+extra(m.id)+'</div>').join('')).join('');
  document.querySelectorAll('.m').forEach(el => el.onclick = () => openSheet(el.dataset.id));
  renderTeams();
}
const esc = s => String(s).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
