const LOGO_STOP = new Set('fc cf afc ac as sc ssc us ud cd rc rcd ca ogc fk sv vfl vfb fsv tsg calcio club de 1 04 05 07 1907 1909 1913 29'.split(' '));
const pickOf = id => (S.pick && S.pick[String(id)]) || '';
const _lgc = {};
function clubKey(n){ return String(n == null ? '' : n).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]/g, ''); }
function clubLogo(name){
  const raw = String(name == null ? '' : name); if (!raw) return '';
  if (raw in _lgc) return _lgc[raw];
  let k = clubKey(raw), s = LOGO_SLUGS.has(k) ? k : LOGO_ALIAS[k];
  if (!s) {
    const t = raw.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/&/g, ' ').split(/[^a-z0-9]+/).filter(w => w && !LOGO_STOP.has(w)).join('');
    s = LOGO_SLUGS.has(t) ? t : LOGO_ALIAS[t];
  }
  return _lgc[raw] = s && LOGO_DATA[s] ? LOGO_DATA[s] : '';
}
const tl = (n, eager) => { const u = clubLogo(n); return u ? '<img class="tl" src="'+u+'" alt=""'+(eager ? '' : ' loading="lazy"')+' decoding="async" onerror="this.remove()">' : ''; };
$('#q').oninput = render;

/* ---------- predict sheet ---------- */
function openSheet(id, need){
  const m = matches.find(x => String(x.id) === String(id)); if (!m) return;
  const sel = pickOf(id), d = dist(id), mine = S.mine[id], fin = /finish|ft/i.test(m.st) || S.locked.includes(String(id));
  const p = d.p || [0,0,0];
  $('#sbody').innerHTML = '<div class="shd"><div>'+crest(m.home, m.hid)+'<b>'+esc(m.home)+'</b></div><span>VS</span><div>'+crest(m.away, m.aid)+'<b>'+esc(m.away)+'</b></div></div><div class="sub"><span>'+esc(m.league)+'</span><span>'+esc(m.time)+'</span></div>' +
    '<div class="pkt'+(need?' need':'')+'"><div class="pkh">'+(sel?'Your team':'Choose your team')+'<small>Goal celebration and live alerts follow this team</small></div><div class="pkr">'+[['h',m.home],['a',m.away]].map(a => '<button class="pkb'+(sel===a[0]?' on':'')+'" data-t="'+a[0]+'">'+tl(a[1],1)+'<span>'+esc(a[1])+'</span></button>').join('')+'</div></div>' +
    '<button class="wl" id="wl"><i></i>Watch Live</button>' +
    '<div class="picks">'+[['1','Home',0],['X','Draw',1],['2','Away',2]].map(a =>
      '<button class="pk '+(mine===a[0]?'on':'')+'" data-p="'+a[0]+'" '+(fin?'disabled':'')+'>'+a[1]+'<b>'+(d.p?p[a[2]]+'%':'–')+'</b></button>').join('')+'</div>' +
    '<div class="sub"><span>'+d.n+' predictions'+(fin?' · closed':'')+'</span><span>'+(mine?'Your pick: '+mine:'')+'</span></div>' +
    '<button class="big wide" id="sm">Show match</button>' + (/finish|full|ft/i.test(m.st||'') ? '<button class="big wide" id="mom" style="background:linear-gradient(90deg,#3d8bff,#7fd8ff)">⭐ Man of the Match</button>' : '') +
    (isOwner ? '<details class="ow"><summary>👑 Owner tools</summary><div class="og4"><button class="ghost" data-o="1">👑 Home</button><button class="ghost" data-o="X">👑 Draw</button><button class="ghost" data-o="2">👑 Away</button><button class="ghost" data-o="">Clear</button></div><div class="og"><button class="ghost" id="hide">Hide match</button><button class="ghost" id="ft">'+(S.feat===m.id?'Unpin':'📌 Pin')+'</button><button class="ghost" id="lk">'+(S.locked.includes(m.id)?'🔓 Unlock':'🔒 Lock')+'</button></div><div class="row"><input type="text" id="sp" placeholder="👑 Score pick, e.g. 2-1" value="'+esc(S.score[m.id]||'')+'" style="flex:1"><button class="ghost" id="spb">Set</button></div><div class="og2"><button class="ghost" id="wp">✍️ AI post</button><button class="ghost" id="shr">Share</button><button class="ghost" id="znt">🔔 Test alerts</button></div></details>' : '') +
    '<div class="row" style="margin-top:14px"><button class="ghost" id="close">Close</button></div>';
  $('#sheet').classList.add('on');
  document.querySelectorAll('.pk').forEach(b => b.onclick = () => vote(id, b.dataset.p));
  document.querySelectorAll('[data-o]').forEach(b => b.onclick = () => { if (b.dataset.o) S.official[id] = b.dataset.o; else delete S.official[id]; save(); hap('medium'); render(); openSheet(id); });
  const h = $('#hide'); if (h) h.onclick = () => { S.hidden.push(m.id); save(); $('#sheet').classList.remove('on'); load(); };
  $('#close').onclick = () => $('#sheet').classList.remove('on');
  $('#sm').onclick = () => showMatch(m);
  $('#wl').onclick = () => watchLive(m);
  document.querySelectorAll('.pkb').forEach(b => b.onclick = () => { const k = String(id); S.pick = S.pick || {}; if (S.pick[k] === b.dataset.t) delete S.pick[k]; else S.pick[k] = b.dataset.t; const ks = Object.keys(S.pick); if (ks.length > 60) delete S.pick[ks[0]]; save(); hap('medium'); openSheet(id); if (window.znKick) znKick(); });
  if ($('#mom')) $('#mom').onclick = () => showMotm(m);
  if (isOwner) {
    $('#ft').onclick = () => { S.feat = S.feat === m.id ? '' : m.id; save(); render(); openSheet(id); };
    $('#lk').onclick = () => { const i = S.locked.indexOf(m.id); i < 0 ? S.locked.push(m.id) : S.locked.splice(i,1); save(); render(); openSheet(id); };
    $('#spb').onclick = () => { const v = $('#sp').value.trim(); v ? S.score[m.id] = v : delete S.score[m.id]; save(); hap('medium'); render(); openSheet(id); };
    $('#wp').onclick = () => writePost(m);
    $('#shr').onclick = () => shareMatch(m);
    $('#znt').onclick = () => { $('#sheet').classList.remove('on'); if (window.znDemo) znDemo(m); };
  }
}
$('#sheet').onclick = e => { if (e.target.id === 'sheet') $('#sheet').classList.remove('on') };
function vote(id, p){ if (S.locked.includes(String(id))) return;
  const i = {1:0,X:1,2:2}, v = S.votes[id] = S.votes[id] || [0,0,0];
  if (S.mine[id]) v[i[S.mine[id]]] = Math.max(0, v[i[S.mine[id]]] - 1);
  v[i[p]]++; S.mine[id] = p; save(); hap('medium'); render(); openSheet(id);
}

