(function(){
  const px24 = (inner, w) => 'url("data:image/svg+xml,' + encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="'+(w||24)+'" height="'+(w||24)+'" viewBox="0 0 '+(w||24)+' '+(w||24)+'">'+inner+'</svg>') + '")';
  const F = 'fill="#fff" fill-opacity=".10"', S = 'stroke="#fff" stroke-opacity=".13" fill="none"';
  const PAT = {
    check: px24('<rect width="12" height="12" '+F+'/><rect x="12" y="12" width="12" height="12" '+F+'/>'),
    dots: px24('<circle cx="6" cy="6" r="2.4" '+F+'/><circle cx="18" cy="18" r="2.4" '+F+'/>'),
    stripes: px24('<path d="M-2 22L22 -2M10 26L26 10" '+S+' stroke-width="5"/>'),
    stars: px24('<path d="M12 3l2 6h6l-5 4 2 6-5-4-5 4 2-6-5-4h6z" '+F+'/>', 28),
    waves: px24('<path d="M0 8q6-6 12 0t12 0M0 20q6-6 12 0t12 0" '+S+' stroke-width="2"/>'),
    grid: px24('<path d="M0 .5H24M.5 0V24" '+S+'/>'),
    bubbles: px24('<circle cx="8" cy="9" r="5" '+S+' stroke-width="2"/><circle cx="19" cy="19" r="3" '+S+' stroke-width="2"/>'),
    splat: px24('<circle cx="7" cy="7" r="5" '+F+'/><circle cx="19" cy="15" r="3" '+F+'/><circle cx="9" cy="20" r="2" '+F+'/>', 28),
    film: px24('<rect x="2" y="2" width="5" height="7" rx="1" '+F+'/><rect x="2" y="15" width="5" height="7" rx="1" '+F+'/><rect x="17" y="2" width="5" height="7" rx="1" '+F+'/><rect x="17" y="15" width="5" height="7" rx="1" '+F+'/>'),
    pitch: px24('<path d="M0 12H24M12 0V24" '+S+' stroke-width="1.5"/><circle cx="12" cy="12" r="6" '+S+' stroke-width="1.5"/>', 48),
    rays: px24('<path d="M0 24L12 0 24 24M12 24V0" '+S+'/>'),
    eq: px24('<rect x="2" y="10" width="4" height="14" '+F+'/><rect x="10" y="2" width="4" height="22" '+F+'/><rect x="18" y="14" width="4" height="10" '+F+'/>')
  };
  const css = THEMES.map(t => '.ch[data-th="'+t[0]+'"]{--bg:'+(PAT[t[4]] || 'none')+' 0 0/'+(t[4]==='pitch'?'48px':'24px')+',linear-gradient(105deg,'+t[2]+'e6 0%,'+t[3]+'e6 100%)}').join('');
  const st = document.createElement('style'); st.id = 'zl-th'; st.textContent = css; document.head.appendChild(st);
  const RE = THEMES.map(t => new RegExp(t[1], 'i')), memo = new Map(), gen = new Set(), PN = Object.keys(PAT), EM = ['📺','✨','🌟','📡','🎯','🔷','🌀','💫','🎪','🎬','🔆','🧿'];
  window.themeOf = function(name){
    name = String(name || ''); if (memo.has(name)) return memo.get(name);
    let r = null; for (let i = 0; i < RE.length; i++) if (RE[i].test(name)) { r = {k:THEMES[i][0], em:THEMES[i][5]}; break; }
    if (!r) {   // no known brand: build a look from the channel name so EVERY channel has a pattern and neighbours differ
      let h = 7; for (let i = 0; i < name.length; i++) h = (h * 31 + name.charCodeAt(i)) >>> 0;
      const hue = (h % 24) * 15, pn = PN[(h >>> 5) % PN.length], k = 'g' + hue + '-' + pn;
      if (!gen.has(k)) { gen.add(k); st.textContent += '.ch[data-th="'+k+'"]{--bg:'+PAT[pn]+' 0 0/'+(pn==='pitch'?'48px':'24px')+',linear-gradient(105deg,hsla('+hue+',62%,34%,.9) 0%,hsla('+((hue+45)%360)+',66%,15%,.9) 100%)}'; }
      r = {k, em: EM[(h >>> 11) % EM.length]};
    }
    memo.set(name, r); return r;
  };
})();
function chRow(name, i, o){
  o = o || {}; const t = themeOf(name);
  return '<div class="ch'+(o.on?' on':'')+'" data-i="'+i+'"'+(t?' data-th="'+t.k+'" data-em="'+t.em+'"':'')+'>'
    +(o.num?'<b class="fbn">'+o.num+'</b>':'')
    +'<span>'+esc(name)+(o.q?'<i class="ql">'+o.q+'p</i>':'')+'</span>'
    +(isOwner?'<button class="ghost bc" data-bc="'+i+'" aria-label="Broadcast to everyone">📢</button>':'')
    +'<button class="ghost">Play</button></div>';
}
function toast(m){ let t = document.getElementById('zlt'); if (!t) { t = document.createElement('div'); t.id = 'zlt'; document.body.appendChild(t); } t.textContent = m; t.classList.add('on'); clearTimeout(toast.t); toast.t = setTimeout(() => t.classList.remove('on'), 3800); }

function setName(n){ $('#cn').textContent = n || ''; $('#cn').hidden = !n; }
const autoplay = () => v.play().catch(() => { v.muted = true; v.play().catch(()=>{}); });
function play(url, name, tried){
  $('#err').textContent = ''; $('#ph').style.display = 'none'; if (hls) { hls.destroy(); hls = null; }
  if (name != null) setName(name); if (!tried) { play.r = 0; curPlay = {u:url, name: name != null ? name : (curPlay ? curPlay.name : '')}; }
  const src = tried === 'p' ? px(url) : url;
  const isHls = /\.m3u8|\/hls|playlist|manifest/i.test(url) || !/\.(mp4|webm|ogg|mkv|ts)(\?|$)/i.test(url);
  v.onerror = () => fail(url, name, tried);
  if (isHls && window.Hls && Hls.isSupported()) {
    hls = new Hls({maxBufferLength:30, enableWorker:true});
    hls.loadSource(src); hls.attachMedia(v);
    hls.on(Hls.Events.MANIFEST_PARSED, autoplay);
    hls.on(Hls.Events.ERROR, (_, d) => { if (!d.fatal) return; if (d.type === Hls.ErrorTypes.MEDIA_ERROR && !play.r) { play.r = 1; hls.recoverMediaError(); return; } fail(url, name, tried); });
  } else { v.src = src; autoplay(); }
}
function fail(url, name, tried){
  if (!tried && /^http:/i.test(url)) return play(url.replace(/^http:/i, 'https:'), name, 's');   // try https version
  if (tried !== 'p' && PROXY) return play(url, name, 'p');                                        // then the proxy
  if (hls) { hls.destroy(); hls = null; }
  $('#ph').style.display = 'grid'; $('#ph').textContent = 'Stream did not start';
  $('#err').textContent = isOwner ? 'Could not play this link. It is offline, blocked by CORS, or http:// only (Mini Apps need https://). Set PROXY in the script to fix CORS/http links.' : 'This channel is unavailable right now. Try another one.';
}
function renderChs(){
  const q = $('#chq').value.toLowerCase(), many = chans.length > 1;
  $('#chq').hidden = chans.length < 12; $('#chh').hidden = !many;
  $('#chs').innerHTML = many ? chans.map((c,i) => [c,i]).filter(x => x[0].name.toLowerCase().includes(q)).slice(0,400).map(x =>
    chRow(x[0].name, x[1], {on:x[1]===curCh})).join('') : '';
  document.querySelectorAll('#chs .ch').forEach(el => el.onclick = e => { if (e.target.dataset.bc != null) { const k = chans[+el.dataset.i]; return goLive({name:k.name, u:k.u}); } curCh = +el.dataset.i; play(chans[curCh].u, chans[curCh].name); renderChs(); hap(); });
}
$('#chq').oninput = renderChs;
async function loadLink(url, name){
  url = (url || '').trim(); if (!url) return; chans = []; curCh = -1; renderChs();
  let txt = null;
  for (const u of [url, PROXY && px(url)].filter(Boolean)) { try { const t = await (await fetch(u)).text(); if (t.includes('#EXTM3U') || t.includes('#EXT-X-')) { txt = t; break; } } catch(e){} }
  if (txt && txt.includes('#EXTINF') && !txt.includes('#EXT-X-')) {
    const L = txt.split(/\r?\n/);
    for (let i = 0; i < L.length; i++) if (L[i].startsWith('#EXTINF')) {
      let j = i + 1; while (j < L.length && (!L[j].trim() || L[j].startsWith('#'))) j++;
      const u = (L[j] || '').trim(); if (!/^https?:/i.test(u)) continue;
      const nm = L[i].slice(L[i].lastIndexOf(',') + 1).trim() || ((L[i].match(/tvg-name="([^"]*)"/) || [])[1] || '').trim() || 'Channel ' + (chans.length + 1);
      chans.push({name: nm, u});
    }
    renderChs();
    if (chans.length === 1) { curCh = 0; play(chans[0].u, chans[0].name); }
    else if (chans.length) { $('#ph').style.display = 'grid'; $('#ph').textContent = 'Pick a channel below'; setName(''); }
    else { $('#ph').style.display = 'grid'; $('#ph').textContent = 'Playlist is empty'; }
  } else play(url, name || '');
}
async function initIptv(){
  if (iptvInit) return; iptvInit = true; pollAir(); setInterval(() => { if (!document.hidden) pollAir(); }, 8e3); catLoadData().catch(() => {});
  let c = IPTV_DEFAULT;
  if (IPTV_CONFIG_URL) { try { c = await (await fetch(IPTV_CONFIG_URL, {cache:'no-store'})).json(); } catch(e){} }
  if (isOwner && S.iptv && S.iptv.url) c = S.iptv;
  if (isOwner) { $('#lown').hidden = false; $('#sv').hidden = false; $('#url').value = (c && c.url) || ''; $('#cname').value = (c && c.name) || ''; }
  if (c && c.url) loadLink(c.url, c.name); else $('#ph').textContent = isOwner ? 'Paste a link and press Play' : 'No channel is live right now';
}
$('#go').onclick = () => { hap('medium'); const u = $('#url').value.trim(), n = $('#cname').value.trim(); if (!u) return; S.iptv = {url:u, name:n}; save(); loadLink(u, n); };
$('#fs').onclick = async () => { const p = $('#pl');
  if (document.fullscreenElement || document.webkitFullscreenElement || p.classList.contains('pfs')) { zlFsExit(p); return; }
  let native = false; const rq = p.requestFullscreen || p.webkitRequestFullscreen;
  if (rq) { try { await rq.call(p); native = true; } catch(e){} }
  let locked = false; try { await screen.orientation.lock('landscape'); locked = true; } catch(e){}
  if (native && !locked && matchMedia('(orientation:portrait)').matches) { try { (document.exitFullscreen || document.webkitExitFullscreen).call(document); } catch(e){} native = false; }
  if (!native) { p.classList.add('pfs'); if (!locked) p.classList.add('rot'); }
  $('#fs').textContent = '✕ Exit'; };
function zlFsExit(p){ p.classList.remove('pfs','rot'); try { if (document.fullscreenElement || document.webkitFullscreenElement) (document.exitFullscreen || document.webkitExitFullscreen).call(document); } catch(e){} try { screen.orientation.unlock(); } catch(e){} $('#fs').textContent = '⛶ Full'; }
['fullscreenchange','webkitfullscreenchange'].forEach(ev => document.addEventListener(ev, () => { if (!document.fullscreenElement && !document.webkitFullscreenElement && !$('#pl').classList.contains('pfs')) { try { screen.orientation.unlock(); } catch(e){} $('#fs').textContent = '⛶ Full'; } }));
$('#pip').onclick = () => { if (document.pictureInPictureEnabled) v.requestPictureInPicture().catch(()=>{}); };
$('#pub').onclick = () => { try { navigator.clipboard.writeText(JSON.stringify({url:$('#url').value.trim(), name:$('#cname').value.trim()})); $('#pub').textContent = 'Copied'; } catch(e){} };
$('#save').onclick = () => {
  const u = $('#url').value.trim(); if (u && !S.saved.includes(u)) { S.saved.unshift(u); S.saved = S.saved.slice(0,30); save(); renderSaved(); hap(); }
};
function renderSaved(){
  $('#saved').innerHTML = S.saved.map((u,i) => '<div class="ch"><span data-p="'+i+'">'+esc(u)+'</span><button class="ghost" data-d="'+i+'">✕</button></div>').join('') || '<div class="empty">No saved links.</div>';
  document.querySelectorAll('[data-p]').forEach(el => el.onclick = () => { $('#url').value = S.saved[el.dataset.p]; loadLink(S.saved[el.dataset.p], $('#cname').value.trim()); });
  document.querySelectorAll('[data-d]').forEach(el => el.onclick = e => { e.stopPropagation(); S.saved.splice(el.dataset.d,1); save(); renderSaved(); });
}

