const isOfficial = name => { const n = chN(name); if (SET_X.has(n)) return true; if (SET_B.has(chClub(name))) return true; if (BAD_CH.test(n)) return false; return SET_A.some(a => n.includes(a)); };
const GOOD_T = /highlight|goals?\b|extended|full match|full game|replay|resumen|resumo|resume|résumé|sintesi|zusammenfassung|melhores momentos|gols|goles|tore|buts|\bvs?\b|\bv\b|\d+\s*[-–:]\s*\d+/i;
