async function playHl(x){
  const b = $('#hlp'); b.hidden = false; $('#hlyt').hidden = false; $('#hlyt').onclick = () => ytOpen(x.id); window.scrollTo({top:0, behavior:'smooth'}); hap();
  try { ytP && ytP.destroy(); } catch(e){} ytP = null;
  b.innerHTML = '<div id="ytp"></div>';
  const ok = await ytApi();
  if (!ok) { b.innerHTML = '<iframe src="https://www.youtube.com/embed/' + encodeURIComponent(x.id) + '?autoplay=1&playsinline=1&rel=0" allow="autoplay; fullscreen; picture-in-picture; encrypted-media" allowfullscreen></iframe>'; return; }
  ytP = new YT.Player('ytp', {host:'https://www.youtube.com', videoId:x.id, width:'100%', height:'100%', playerVars:{autoplay:1, playsinline:1, rel:0, modestbranding:1},
    events:{ onError: e => { if ([2,5,100,101,150,153].includes(+e.data)) ytBlocked(x.id); } }});
}
async function ytSearch(q, after){
  const u = 'https://www.googleapis.com/youtube/v3/search?part=snippet&type=video&videoEmbeddable=true&videoSyndicated=true&order=date&maxResults=50&publishedAfter=' + encodeURIComponent(after) + '&q=' + encodeURIComponent(q) + '&key=' + YT_KEY;
  const j = await (await fetch(u)).json();
  if (j.error) throw new Error(/quota/i.test(j.error.message) ? 'Daily video quota reached. Try again tomorrow.' : /key|permission|denied/i.test(j.error.message) ? 'The video key is not valid.' : j.error.message);
  return j.items || [];
}
async function loadHl(k){
  hlk = k; chips($('#hlc'), HL.map(x => [x[0], x[1]]), k, loadHl);
  if (!YT_KEY) { $('#hls').textContent = ''; $('#hll').innerHTML = '<div class="empty">' + (isOwner ? 'Add your video API key to YT_KEY in the script to show real highlights.' : 'Highlights are coming soon.') + '</div>'; return; }
  const ck = 'zl_hl2_' + k; let items = null;
  try { const c = JSON.parse(localStorage.getItem(ck)); if (c && Date.now() - c.t < 18e5) items = c.d } catch(e){}
  if (!items) {
    $('#hll').innerHTML = '<div class="empty">Loading latest highlights…</div>';
    try {
      const after = new Date(Date.now() - 5*864e5).toISOString(), nm = HL.find(x => x[1] === k)[2];
      const qs = [nm + ' highlights', nm + ' full match goals'];
      const res = await Promise.all(qs.map(q => ytSearch(q, after).catch(e => e)));
      const bad = res.find(r => r instanceof Error); if (bad && res.every(r => r instanceof Error)) throw bad;
      const seen = new Set();
      items = [].concat(...res.filter(Array.isArray)).filter(i => i.id && i.id.videoId && !seen.has(i.id.videoId) && seen.add(i.id.videoId))
        .filter(i => i.snippet.liveBroadcastContent === 'none' && isOfficial(i.snippet.channelTitle) && GOOD_T.test(dec(i.snippet.title)) && !BAD_T.test(dec(i.snippet.title)))
        .sort((a, b) => new Date(b.snippet.publishedAt) - new Date(a.snippet.publishedAt))
        .map(i => ({id:i.id.videoId, t:dec(i.snippet.title), ch:dec(i.snippet.channelTitle), at:i.snippet.publishedAt, img:(i.snippet.thumbnails.medium || i.snippet.thumbnails.default).url}));
      try { localStorage.setItem(ck, JSON.stringify({t:Date.now(), d:items})) } catch(e){}
    } catch(e){ $('#hls').textContent = ''; $('#hll').innerHTML = '<div class="empty">Could not load highlights.<br><b>' + esc(e.message) + '</b><br><br><button class="ghost" id="hlr">Try again</button></div>'; $('#hlr').onclick = () => loadHl(k); return; }
  }
  $('#hls').textContent = items.length + ' official highlights · ' + CH_COUNT + ' channels allowed · newest first';
  $('#hll').innerHTML = items.map((x,i) => '<div class="hv" data-i="'+i+'"><img loading="lazy" src="'+esc(x.img)+'" alt=""><div><b>'+esc(x.t)+'</b><small>'+esc(x.ch)+' · '+ago(x.at)+'</small></div></div>').join('') || '<div class="empty">No official highlights in the last 5 days.</div>';
  document.querySelectorAll('#hll .hv').forEach(el => el.onclick = () => playHl(items[+el.dataset.i]));
}

