/* ===== owner perks ===== */
const badge = m => /live|half|first|second|extra|penalt/i.test(m.st||'') ? '<small class="lvb">● '+(/half/i.test(m.st||'') ? 'HT' : m.min ? m.min + "'" : 'LIVE')+'</small>' : /finish|ft/i.test(m.st||'') ? '<small class="ftb">FT</small>' : '';
const extra = id => (S.score[id] || S.locked.includes(id)) ? '<div class="sub"><span>'+(S.score[id] ? '👑 Score pick ' + esc(S.score[id]) : '')+'</span><span>'+(S.locked.includes(id) ? '🔒 Voting closed' : '')+'</span></div>' : '';
function shareText(t){ const u = 'https://t.me/share/url?url=' + encodeURIComponent(location.href.split('#')[0]) + '&text=' + encodeURIComponent(t); tg && tg.openTelegramLink ? tg.openTelegramLink(u) : window.open(u, '_blank'); }
