  $('#sbody').innerHTML = '<h3 style="font-size:16px">Your post</h3>' + (d ? '<textarea id="pt" rows="8" style="width:100%;margin-top:10px;background:var(--bg2);border:1px solid var(--line);border-radius:14px;padding:12px;color:var(--tx);font:inherit">' + esc(d.post || '') + '</textarea>' : '<div class="err">' + esc(err || 'No post') + '</div>') + '<div class="row" style="margin-top:12px"><button class="big" id="pcp">Copy</button><button class="ghost" id="psh">Share</button><button class="ghost" id="pbk">Back</button></div>';
  $('#sheet').classList.add('on');
  $('#pcp').onclick = () => { try { navigator.clipboard.writeText($('#pt').value) } catch(e){} hap('medium'); };
  $('#psh').onclick = () => d && shareText($('#pt').value);
