  document.querySelectorAll('[data-bs]').forEach(b => { b.classList.toggle('on', b.dataset.bs === S.bst); b.onclick = () => { S.bst = b.dataset.bs; save(); showBanner(); document.querySelectorAll('[data-bs]').forEach(x => x.classList.toggle('on', x === b)); hap(); }; });
  $('#cc').onclick = () => { Object.keys(localStorage).filter(k => /^(zl_|zl4k_fx_)/.test(k)).forEach(k => localStorage.removeItem(k)); hap('medium'); $('#cc').textContent = 'Cleared'; };
  $('#bk').onclick = () => { try { navigator.clipboard.writeText(JSON.stringify(S)); $('#bk').textContent = 'Copied'; } catch(e){} };
