;

/* ===== ZSocial: ZPost (RSS news) + ZReel (YouTube). Separate script block so it can never break the app above. ===== */
(function(){
'use strict';
const SWIPE_RIGHT_OPENS_REEL = true;   // your spec: swipe right -> ZReel, swipe left -> ZPost. Set false for the usual opposite.
const REFRESH_MS = 5 * 60 * 1000;
const ZS_API_URL = 'https://zsocial.kidusspro777.workers.dev'; // leave empty to use your existing worker; or paste your NEW ZSocial worker URL, e.g. 'https://zsocial.YOURNAME.workers.dev'
let API; try { API = ZS_API_URL || new URL(SHOWS_URL).origin } catch(e) { API = ZS_API_URL || 'https://zeroshow.kidusspro777.workers.dev' }
const $ = s => document.querySelector(s);
const sec = $('#t-zsocial'), pager = $('#zsPager'), pPost = $('#zsPost'), pReel = $('#zsReel');
if (!sec || !pager) return;
const tgw = window.Telegram && Telegram.WebApp;
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl = u => { try { const x = new URL(u); return /^https?:$/.test(x.protocol) ? x.href : '' } catch(e){ return '' } };

/* order of panes: with SWIPE_RIGHT_OPENS_REEL the reel pane sits on the left so the motion matches the finger */
const order = SWIPE_RIGHT_OPENS_REEL ? ['reel','post'] : ['post','reel'];
pager.append(...order.map(k => k === 'post' ? pPost : pReel));
let feed = 'post', W = 0;
const likes = (() => { try { return JSON.parse(localStorage.getItem('zs_likes')) || {} } catch(e){ return {} } })();
const saveLikes = () => { try { localStorage.setItem('zs_likes', JSON.stringify(likes)) } catch(e){} };

/* ---------- layout / sizing ---------- */
function size(){
  const nav = document.querySelector('nav'); if (nav) sec.style.setProperty('--zsnav', nav.offsetHeight + 'px');
  W = pager.parentElement.clientWidth || innerWidth;
  if (pReel.clientHeight > 80) pReel.style.setProperty('--zsh', pReel.clientHeight + 'px');
  place(false);
}
function place(anim, dx){
  pager.classList.toggle('drag', !anim);
  const base = -order.indexOf(feed) * W;
  pager.style.transform = 'translateX(' + (base + (dx || 0)) + 'px)';
}
addEventListener('resize', () => sec.classList.contains('on') && size());
addEventListener('orientationchange', () => setTimeout(() => sec.classList.contains('on') && size(), 250));

/* ---------- feed switching (tabs + swipe) ---------- */
const saved = {post:0, reel:0};
function setFeed(f){
  if (f === feed) { place(true); return; }
  feed = f;
  document.querySelectorAll('.zs-tabs button').forEach(b => b.classList.toggle('on', b.dataset.zs === f));
  place(true);
  if (f === 'reel') { loadReels(true); watchReel(); } else { unmountPlayer(); }
}
document.querySelectorAll('.zs-tabs button').forEach(b => b.onclick = () => setFeed(b.dataset.zs));

let sx = 0, sy = 0, axis = null, dxm = 0;
pager.addEventListener('touchstart', e => { if (e.touches.length !== 1) return; sx = e.touches[0].clientX; sy = e.touches[0].clientY; axis = null; dxm = 0; }, {passive:true});
pager.addEventListener('touchmove', e => {
  if (e.touches.length !== 1 || axis === 'y') return;
  const dx = e.touches[0].clientX - sx, dy = e.touches[0].clientY - sy;
  if (!axis) { if (Math.abs(dx) < 12 && Math.abs(dy) < 12) return; axis = Math.abs(dx) > Math.abs(dy) * 1.8 ? 'x' : 'y'; if (axis === 'y') return; }
  /* only allow dragging toward the other feed, with a little resistance */
  const target = dx > 0 === SWIPE_RIGHT_OPENS_REEL ? 'reel' : 'post';
  if (target === feed) { dxm = 0; place(false, 0); return; }
  dxm = dx; place(false, Math.max(-W, Math.min(W, dx)));
}, {passive:true});
function endTouch(){
  if (axis === 'x' && Math.abs(dxm) > Math.min(90, W * .22)) setFeed(dxm > 0 === SWIPE_RIGHT_OPENS_REEL ? 'reel' : 'post'); else place(true);
  axis = null; dxm = 0;
}
pager.addEventListener('touchend', endTouch, {passive:true});
pager.addEventListener('touchcancel', () => { axis = null; dxm = 0; place(true); }, {passive:true});

/* ---------- fake local Like (never sent anywhere) ---------- */
const HEART = '<svg viewBox="0 0 24 24"><path d="M12 21s-7.5-4.6-9.5-9.2C1.2 8.4 3 5 6.4 5c2 0 3.6 1.1 4.6 2.7h2C14 6.1 15.6 5 17.6 5 21 5 22.8 8.4 21.5 11.8 19.5 16.4 12 21 12 21z"/></svg>';
const likeBtn = id => { const on = !!likes[id]; return '<button class="zs-like' + (on ? ' on' : '') + '" data-lk="' + esc(id) + '" aria-label="Like" aria-pressed="' + on + '">' + HEART + '<span class="n">' + (on ? '1' : '') + '</span></button>'; };
sec.addEventListener('click', e => {
  const y = e.target.closest('[data-yt]'); if (y) { const u = 'https://www.youtube.com/watch?v=' + encodeURIComponent(y.dataset.yt); try { tgw && tgw.openLink ? tgw.openLink(u) : open(u, '_blank') } catch(_){ open(u, '_blank') } return; }
  const b = e.target.closest('.zs-like'); if (b) {
    const id = b.dataset.lk, on = !likes[id];
    if (on) likes[id] = 1; else delete likes[id];
    b.classList.toggle('on', on); b.setAttribute('aria-pressed', on); b.querySelector('.n').textContent = on ? '1' : '';
    saveLikes(); try { tgw.HapticFeedback.impactOccurred('light') } catch(_){} return;
  }
  const a = e.target.closest('a.zp-t'); if (a && tgw && tgw.openLink) { e.preventDefault(); try { tgw.openLink(a.href) } catch(_){ open(a.href, '_blank') } }
});

/* ---------- helpers ---------- */
function ago(iso){ const t = Date.parse(iso); if (!t) return ''; const s = Math.max(0, (Date.now() - t) / 1000);
  if (s < 90) return 'now'; if (s < 3600) return Math.round(s / 60) + 'm'; if (s < 86400) return Math.round(s / 3600) + 'h'; if (s < 604800) return Math.round(s / 86400) + 'd';
  return new Date(t).toLocaleDateString(undefined, {day:'numeric', month:'short'}); }
async function api(path){ const r = await fetch(API + path, {cache:'no-store'}); if (!r.ok) throw new Error('HTTP ' + r.status); return r.json(); }
const skPost = n => Array.from({length:n}, () => '<div class="zs-sk"><i style="width:55%;height:14px;margin-bottom:12px"></i><i style="aspect-ratio:16/10;margin:0 -14px 12px;border-radius:0"></i><i style="width:90%;height:14px;margin-bottom:8px"></i><i style="width:70%;height:12px"></i></div>').join('');
const msg = (t, s) => '<div class="zs-msg"><b>' + esc(t) + '</b>' + esc(s) + '</div>';

/* ---------- ZPost ---------- */
const P = {items:[], ids:new Set(), offset:0, total:0, busy:false, done:false, started:false, retry:0};
function postCard(x){
  const img = safeUrl(x.image), link = safeUrl(x.link);
  return '<article class="zp" data-id="' + esc(x.id) + '"><div class="zp-h"><span class="zp-av">' + esc((x.source || '?').trim().charAt(0).toUpperCase()) + '</span><div><b>' + esc(x.source) + '</b><small>' + esc(ago(x.published)) + '</small></div></div>'
   + (img ? '<img class="zp-img" loading="lazy" referrerpolicy="no-referrer" src="' + esc(img) + '" alt="" onerror="this.remove()">' : '')
   + '<div class="zp-b">' + likeBtn(x.id) + (link ? '<a class="zp-t" href="' + esc(link) + '" target="_blank" rel="noopener noreferrer">' + esc(x.title) + '</a>' : '<span class="zp-t">' + esc(x.title) + '</span>')
   + (x.caption ? '<p class="zp-c">' + esc(x.caption) + '</p>' : '') + '</div></article>';
}
async function loadPosts(reset){
  if (P.busy || (P.done && !reset)) return;
  P.busy = true;
  if (!P.started) pPost.innerHTML = skPost(3);
  try {
    const d = await api('/zsocial/posts?offset=' + (reset ? 0 : P.offset) + '&limit=15');
    const fresh = (d.items || []).filter(x => !P.ids.has(x.id));
    if (!P.started) { pPost.innerHTML = ''; P.started = true; }
    fresh.forEach(x => P.ids.add(x.id)); P.items.push(...fresh);
    pPost.querySelectorAll('.zs-end,.zs-sk').forEach(n => n.remove());
    if (fresh.length) pPost.insertAdjacentHTML('beforeend', fresh.map(postCard).join(''));
    P.offset = d.nextOffset == null ? P.offset : d.nextOffset; P.total = d.total || 0; P.done = d.nextOffset == null; P.retry = 0;
    if (!P.items.length) pPost.innerHTML = msg('No stories yet', 'Football news will appear here as soon as the sources respond.');
    else if (P.done) pPost.insertAdjacentHTML('beforeend', '<div class="zs-end">You are all caught up</div>');
    else pPost.insertAdjacentHTML('beforeend', '<div class="zs-sk">' + skPost(1) + '</div>');
  } catch(e) {
    if (!P.started) pPost.innerHTML = msg('Could not load the news', 'Trying again automatically…');
    const wait = Math.min(60000, 6000 * Math.pow(2, P.retry++)); setTimeout(() => { P.busy = false; if (sec.classList.contains('on')) loadPosts(); }, wait);
    return;
  }
  P.busy = false;
}
pPost.addEventListener('scroll', () => { if (pPost.scrollTop + pPost.clientHeight > pPost.scrollHeight - 900) loadPosts(); }, {passive:true});
async function refreshPosts(){ /* silent auto-refresh: prepend only genuinely new stories, and only when the reader is at the top */
  if (!P.started || pPost.scrollTop > 40) return;
  try { const d = await api('/zsocial/posts?offset=0&limit=15'); const fresh = (d.items || []).filter(x => !P.ids.has(x.id)); if (!fresh.length) return;
    fresh.forEach(x => P.ids.add(x.id)); P.items.unshift(...fresh); pPost.insertAdjacentHTML('afterbegin', fresh.map(postCard).join('')); } catch(e){}
}

/* ---------- ZReel ---------- */
const R = {items:[], ids:new Set(), offset:0, busy:false, done:false, started:false, retry:0, io:null, cur:null};
function reelCard(x, i){
  const th = safeUrl(x.thumb);
  return '<section class="zr" data-i="' + i + '" data-v="' + esc(x.id) + '"><div class="zr-v">' + (th ? '<img loading="lazy" referrerpolicy="no-referrer" src="' + esc(th) + '" alt="">' : '') + '</div>'
   + '<div class="zr-m"><div><small>' + esc(x.channel) + '</small><b>' + esc(x.title) + '</b></div>' + '<button class="zs-ytb sm" data-yt="' + esc(x.id) + '">▶ Open</button>' + likeBtn('v:' + x.id) + '</div></section>';
}
async function loadReels(first){
  if (R.busy || R.done) { if (first) watchReel(); return; }
  if (first && R.started) { watchReel(); return; }
  R.busy = true;
  if (!R.started) pReel.innerHTML = '<div class="zr"><div class="zr-v"><div class="zs-sk" style="padding:0;height:100%"><i style="height:100%;border-radius:0"></i></div></div></div>';
  try {
    const d = await api('/zsocial/reels?offset=' + R.offset + '&limit=10');
    const fresh = (d.items || []).filter(x => !R.ids.has(x.id));
    if (!R.started) { pReel.innerHTML = ''; R.started = true; }
    pReel.querySelectorAll('.zs-end').forEach(n => n.remove());
    const start = R.items.length; fresh.forEach(x => R.ids.add(x.id)); R.items.push(...fresh);
    if (fresh.length) pReel.insertAdjacentHTML('beforeend', fresh.map((x, k) => reelCard(x, start + k)).join(''));
    R.offset = d.nextOffset == null ? R.offset : d.nextOffset; R.done = d.nextOffset == null; R.retry = 0;
    if (!R.items.length) pReel.innerHTML = '<div class="zr"><div class="zs-msg" style="margin:auto"><b>No videos yet</b>Football videos will appear here once they are available.</div></div>';
    else if (R.done) pReel.insertAdjacentHTML('beforeend', '<div class="zs-end" style="scroll-snap-align:end">You are all caught up</div>');
    size(); requestAnimationFrame(pick);
  } catch(e) {
    if (!R.started) pReel.innerHTML = '<div class="zr"><div class="zs-msg" style="margin:auto"><b>Could not load videos</b>Trying again automatically…</div></div>';
    const wait = Math.min(60000, 6000 * Math.pow(2, R.retry++)); setTimeout(() => { R.busy = false; if (sec.classList.contains('on') && feed === 'reel') loadReels(); }, wait);
    return;
  }
  R.busy = false;
}
function pick(){ /* play whichever card is snapped into view (scroll based: no IntersectionObserver dependence) */
  if (feed !== 'reel' || !sec.classList.contains('on')) return;
  const pr = pReel.getBoundingClientRect(); let best = null, bd = 1e9;
  pReel.querySelectorAll('.zr[data-v]').forEach(c => { const d = Math.abs(c.getBoundingClientRect().top - pr.top); if (d < bd) { bd = d; best = c; } });
  if (best && bd < pr.height * .5) { mountPlayer(best); if (+best.dataset.i >= R.items.length - 3) loadReels(); }
}
let pt = null; pReel.addEventListener('scroll', () => { clearTimeout(pt); pt = setTimeout(pick, 90); }, {passive:true});
function skipCard(c){ if (!c) return; if (R.cur === c) R.cur = null; const f = c.querySelector('iframe'); if (f) f.remove(); const box = c.querySelector('.zr-v'); if (box && !box.querySelector('.zr-fb')) box.insertAdjacentHTML('beforeend', '<div class="zr-fb"><div>This video cannot play inside the app.</div><button class="zs-ytb" data-yt="' + esc(c.dataset.v) + '">▶ Watch video</button></div>'); }
addEventListener('message', e => {
  let h = ''; try { h = new URL(e.origin).hostname } catch(_){ return }
  if (!/(^|\.)youtube(-nocookie)?\.com$/.test(h) || !R.cur) return;
  let d = e.data; if (typeof d === 'string') { try { d = JSON.parse(d) } catch(_){ return } }
  const f = R.cur.querySelector('iframe');
  if (d && d.event === 'onError' && [100, 101, 150, 152].includes(+d.info) && f && e.source === f.contentWindow) skipCard(R.cur);
});
function mountPlayer(card){
  if (R.cur === card) return; unmountPlayer();
  const id = card.dataset.v, box = card.querySelector('.zr-v'); if (!/^[\w-]{11}$/.test(id)) return;
  const f = document.createElement('iframe');
  f.src = 'https://www.youtube.com/embed/' + id + '?autoplay=1&mute=1&playsinline=1&rel=0&loop=1&playlist=' + id + '&modestbranding=1&enablejsapi=1' + (/^https?:/.test(location.origin) ? '&origin=' + encodeURIComponent(location.origin) : '');
  f.onload = () => { try { f.contentWindow.postMessage(JSON.stringify({event:'listening', id:1, channel:'widget'}), '*'); f.contentWindow.postMessage(JSON.stringify({event:'command', func:'addEventListener', args:['onError'], id:1, channel:'widget'}), '*'); } catch(_){} };
  f.allow = 'autoplay; encrypted-media; picture-in-picture; fullscreen'; f.allowFullscreen = true; f.title = 'Football video'; f.referrerPolicy = 'strict-origin-when-cross-origin';
  box.appendChild(f); R.cur = card;
}
function unmountPlayer(){ if (R.cur) { const f = R.cur.querySelector('iframe'); if (f) f.remove(); R.cur = null; } }
function watchReel(){ requestAnimationFrame(() => { size(); setTimeout(pick, 60); }); }

/* ---------- enter / leave the ZSocial tab ---------- */
let timer = null, wasOn = false;
function sync(t){
  const on = t === 'zsocial';
  document.body.classList.toggle('zs', on);
  if (on && !wasOn) {
    size(); loadPosts();
    requestAnimationFrame(() => { pPost.scrollTop = saved.post; pReel.scrollTop = saved.reel; size(); if (feed === 'reel') { loadReels(true); watchReel(); } });
    try { tgw.disableVerticalSwipes && tgw.disableVerticalSwipes(); tgw.setHeaderColor('#000000'); tgw.setBackgroundColor('#000000'); } catch(e){}
    timer = setInterval(refreshPosts, REFRESH_MS);
  }
  if (!on && wasOn) {
    saved.post = pPost.scrollTop; saved.reel = pReel.scrollTop; unmountPlayer(); clearInterval(timer);
    try { tgw.enableVerticalSwipes && tgw.enableVerticalSwipes(); tgw.setHeaderColor('#000000'); tgw.setBackgroundColor('#000000'); } catch(e){}
  }
  wasOn = on;
}
document.querySelectorAll('nav button').forEach(b => b.addEventListener('click', () => sync(b.dataset.t)));
document.addEventListener('visibilitychange', () => { if (document.hidden) unmountPlayer(); else if (wasOn && feed === 'reel') watchReel(); });
})();

