const HDC = {};
function hdUp(src){
  return new Promise(res => {
    if (!src) return res(''); if (HDC[src]) return res(HDC[src]);
    const im = new Image(); const bail = () => res(src); setTimeout(bail, 2500);
    im.onload = () => { try {
      const w = im.naturalWidth, h = im.naturalHeight; if (!w || !h) return bail(); let cur = im, f = 1; const target = Math.max(1, 260/Math.max(w, h));
      while (f < target - .01) { const s = Math.min(2, target/f), c = document.createElement('canvas'); c.width = Math.round(w*f*s); c.height = Math.round(h*f*s); const x = c.getContext('2d'); x.imageSmoothingEnabled = true; x.imageSmoothingQuality = 'high'; x.drawImage(cur, 0, 0, c.width, c.height); cur = c; f *= s; }
      if (cur === im) return bail();
      const x = cur.getContext('2d'), W = cur.width, H = cur.height, d = x.getImageData(0, 0, W, H), s = d.data, o = new Uint8ClampedArray(s), amt = .65;
      for (let y = 1; y < H - 1; y++) for (let q = 1; q < W - 1; q++) { const i = (y*W + q)*4; if (!s[i + 3]) continue; for (let ch = 0; ch < 3; ch++) { const v = s[i + ch]*5 - s[i - 4 + ch] - s[i + 4 + ch] - s[i - W*4 + ch] - s[i + W*4 + ch]; o[i + ch] = s[i + ch] + (v - s[i + ch])*amt; } }
      d.data.set(o); x.putImageData(d, 0, 0); HDC[src] = cur.toDataURL('image/png'); res(HDC[src]);
    } catch(e) { bail(); } };
    im.onerror = bail; im.src = src;
  });
}

/* ===== TOTY intro song: streamed through YouTube's own embedded player (sound only, the video is hidden). Nothing is downloaded or stored. ===== */
const TOTY_SONG = {yt:'xpv9-4apgUM', mp3:'toty_theme', vol:50, start:0}; /* vol = half volume; start = second to start from; mp3 = optional direct audio link you own, used instead of YouTube */
const SONG = (function(){
  let pl = null, ready = false, want = false, au = null, loading = false, started = false, fade = 0;
  function loadAPI(cb){
    if (window.YT && window.YT.Player) return cb();
    if (window.__ytq) { window.__ytq.push(cb); return; }
    window.__ytq = [cb]; const prev = window.onYouTubeIframeAPIReady;
    window.onYouTubeIframeAPIReady = () => { try { if (prev) prev(); } catch(e){} const q = window.__ytq || []; window.__ytq = null; q.forEach(f => { try { f(); } catch(e){} }); };
    const s = document.createElement('script'); s.src = 'https://www.youtube.com/iframe_api'; s.async = true; s.onerror = () => { window.__ytq = null; loading = false; }; document.head.appendChild(s);
  }
  function go(){ try { pl.setVolume(TOTY_SONG.vol); if (TOTY_SONG.start) pl.seekTo(TOTY_SONG.start, true); pl.playVideo(); } catch(e){} }
  function prep(){
    if (TOTY_SONG.mp3) { if (!au) { au = new Audio(window.zfsAudioURL(TOTY_SONG.mp3)); au.preload = 'auto'; au.volume = TOTY_SONG.vol/100; au.onerror = () => { au = null; TOTY_SONG.mp3 = ''; started = false; prep(); }; } return; }
    if (pl || loading) return; loading = true;
    loadAPI(() => { try {
      let h = document.getElementById('zr-yt'); if (!h) { h = document.createElement('div'); h.id = 'zr-yt'; h.innerHTML = '<div id="zr-ytp"></div>'; document.body.appendChild(h); }
      pl = new window.YT.Player('zr-ytp', {width:'200', height:'200', videoId:TOTY_SONG.yt, playerVars:{autoplay:0, controls:0, disablekb:1, fs:0, playsinline:1, rel:0, modestbranding:1, iv_load_policy:3, origin:location.origin}, events:{onReady:() => { ready = true; try { pl.setVolume(TOTY_SONG.vol); } catch(e){} if (want && !started) { started = true; go(); } }, onError:() => { ready = false; }}});
    } catch(e){ loading = false; } });
  }
  function play(){ want = true; if (started) return; if (au) { started = true; try { au.currentTime = TOTY_SONG.start || 0; au.volume = TOTY_SONG.vol/100; au.play().catch(() => {}); } catch(e){} return; } if (ready && pl) { started = true; go(); } }
  function stop(){
    want = false; const was = started; started = false; clearInterval(fade); if (!was) return;
    const out = (set, done) => { let v = TOTY_SONG.vol; fade = setInterval(() => { v -= TOTY_SONG.vol/8; if (v <= 0) { clearInterval(fade); done(); } else set(v); }, 80); };
    if (au) out(v => { au.volume = v/100; }, () => { au.pause(); au.volume = TOTY_SONG.vol/100; });
    else if (pl && ready) out(v => { try { pl.setVolume(v); } catch(e){} }, () => { try { pl.pauseVideo(); pl.setVolume(TOTY_SONG.vol); } catch(e){} });
  }
  return {prep, play, stop};
})();
