  st.innerHTML = '<div class="zo-pack" id="zpk">'+packHTML(k, 1).replace('class="zp','class="zo-half t zp')+packHTML(k, 1).replace('class="zp','class="zo-half b zp')+'</div><div class="zo-flash"></div>'; $('#zo .hint').textContent = 'HOLD TO CHARGE';
  const okc = await RIT.charge(k, $('#zo .hint'), () => closed); if (closed || !okc) return; $('#zo .hint').textContent = '';
