    + '<label>Walkout<select id="sw">'+o('auto', 'Normal rules (Ultimate, TOTY, Rank Up · Epic+)', SIM.walk)+o('ult', 'Force Ultimate style', SIM.walk)+o('toty', 'Force Team of the Year style', SIM.walk)+o('rank', 'Force Rank Up style', SIM.walk)+'</select></label>'
