/* ===== real player faces from the Highlightly API, through your faces worker (the key never touches the app) ===== */
const FACE_URL = window.FACE_URL || 'https://zerocardworker.kidusspro777.workers.dev/';   /* paste your worker URL here, e.g. 'https://zfs-faces.YOURNAME.workers.dev' */
(function(){
  const K = 'zl_faces', M = (() => { try { const o = JSON.parse(localStorage.getItem(K)) || {}; Object.keys(o).forEach(k => { if (!o[k]) delete o[k]; }); return o; } catch(e){ return {}; } })(), pend = {}, NEG = {};
  const sv = () => { try { localStorage.setItem(K, JSON.stringify(M)); } catch(e){} };
  const pickU = j => j && (j.url || j.photo || j.image || j.img || j.face || (j.data && (j.data.url || j.data.image)) || '');
  const ascii = s => s.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  function paint(p){ const u = M[p.n]; if (!u) return; document.querySelectorAll('.zc[data-pid="'+p.id+'"]').forEach(c => { if (c.querySelector('.ph')) return; const i = new Image(); i.className = 'man ph'; i.alt = ''; i.referrerPolicy = 'no-referrer'; i.onload = () => c.classList.add('pok'); i.onerror = () => i.remove(); i.src = u; c.insertBefore(i, c.querySelector('svg.man')); }); }
  const ask = n => fetch(FACE_URL + '?name=' + encodeURIComponent(n)).then(r => r.json()).then(pickU);
  function one(p){ const k = p.n; if (!FACE_URL || p.gen || !(S.zc.cards && S.zc.cards[p.id])) return Promise.resolve(); if (M[k] || NEG[k]) return Promise.resolve(); if (pend[k]) return pend[k];
    return pend[k] = ask(k).then(u => (!u && ascii(k) !== k) ? ask(ascii(k)) : u).then(u => { if (u) { M[k] = u; sv(); paint(p); } else NEG[k] = 1; }).catch(() => {}).then(() => { delete pend[k]; }); }
  window.zfsFaceDebug = async name => { const out = {name, url: FACE_URL}; try { const r = await fetch(FACE_URL + '?name=' + encodeURIComponent(name)); out.status = r.status; const tx = await r.text(); out.body = tx.slice(0, 260); let j = null; try { j = JSON.parse(tx); } catch(e){} out.photo = pickU(j) || ''; if (out.photo) out.image = await new Promise(res => { const i = new Image(); i.referrerPolicy = 'no-referrer'; i.onload = () => res('loads ('+i.naturalWidth+'x'+i.naturalHeight+')'); i.onerror = () => res('FAILS to load (blocked or bad link)'); i.src = out.photo; setTimeout(() => res('timeout'), 6000); }); } catch(e){ out.error = String(e && e.message || e); } return out; };
  window.ZFS_PHOTO = p => { const u = M[p.n]; if (u) return u; one(p); return ''; };
  window.zfsPrefetch = ps => Promise.race([Promise.all(ps.map(one)), new Promise(r => setTimeout(r, 3500))]);
})();
